export function baselineAnswers(){const answers={};for(const question of conferenceQuestions)if(question.kind!=="context"&&!question.primaryOf)answers[question.id]=[question.options[0]];answers.q2=[answers.q1[0]];answers.q21=[answers.q20[0]];answers["q36-geography"]=["Need to remain near my current location"];answers["q36-stakeholders"]=["Decision is primarily mine"];answers["q36-stage"]=["Actively researching franchises"];answers.concerns=[concernExclusive];return answers;}
const persona=(name,overrides)=>({name,answers:{...baselineAnswers(),...overrides}});

